CREATE TABLE public.client_gym_links (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, gym_id uuid NOT NULL REFERENCES public.gyms(id) ON DELETE CASCADE, favorite boolean NOT NULL DEFAULT false, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,gym_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_gym_links TO authenticated; GRANT ALL ON public.client_gym_links TO service_role;
ALTER TABLE public.client_gym_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_client_links ON public.client_gym_links FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.client_membership_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), gym_id uuid NOT NULL, gym_name text NOT NULL, member_record_id text NOT NULL, definition jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.client_membership_history TO authenticated; GRANT ALL ON public.client_membership_history TO service_role;
ALTER TABLE public.client_membership_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership_history ON public.client_membership_history FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.client_membership_history(user_id,gym_id,gym_name,member_record_id,definition) SELECT r.client_id,r.gym_id,g.name,r.id,r.data FROM public.gym_records r JOIN public.gyms g ON g.id=r.gym_id WHERE r.kind='members' AND r.client_id IS NOT NULL;
CREATE FUNCTION public.capture_client_membership() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='members' AND NEW.client_id IS NOT NULL THEN IF TG_OP='INSERT' OR OLD.client_id IS DISTINCT FROM NEW.client_id OR (OLD.data->>'plan',OLD.data->>'start',OLD.data->>'expiry',OLD.data->>'planPrice',OLD.data->>'type',OLD.data->>'sessionsTotal') IS DISTINCT FROM (NEW.data->>'plan',NEW.data->>'start',NEW.data->>'expiry',NEW.data->>'planPrice',NEW.data->>'type',NEW.data->>'sessionsTotal') THEN INSERT INTO public.client_membership_history(user_id,gym_id,gym_name,member_record_id,definition) SELECT NEW.client_id,NEW.gym_id,name,NEW.id,NEW.data FROM public.gyms WHERE id=NEW.gym_id; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_client_membership AFTER INSERT OR UPDATE ON public.gym_records FOR EACH ROW EXECUTE FUNCTION public.capture_client_membership();
CREATE FUNCTION public.client_gym_directory() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN auth.uid() IS NULL THEN '[]'::jsonb ELSE coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'location',coalesce(r.data->>'location',''),'image',coalesce(r.data->>'cover',''),'description',coalesce(r.data->>'description',''))),'[]'::jsonb) END FROM public.gyms g LEFT JOIN public.gym_records r ON r.gym_id=g.id AND r.kind='gym' $$;
REVOKE ALL ON FUNCTION public.client_gym_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.client_gym_directory() TO authenticated;
CREATE FUNCTION public.client_gym_content(g uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR NOT (EXISTS(SELECT 1 FROM public.client_gym_links WHERE user_id=auth.uid() AND gym_id=g) OR EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=auth.uid())) THEN RAISE EXCEPTION 'Join this gym to view its client pages'; END IF; SELECT jsonb_build_object('workouts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',data->>'name','trainer',data->>'trainer','notes',data->>'notes','exercises',data->'exercises')) FROM public.gym_records WHERE gym_id=g AND kind='workouts'),'[]'::jsonb),'products',coalesce((SELECT jsonb_agg(jsonb_build_object('name',data->>'name','price',data->'price','image',data->>'image')) FROM public.gym_records WHERE gym_id=g AND kind='products'),'[]'::jsonb),'trainers',coalesce((SELECT jsonb_agg(jsonb_build_object('name',data->>'name','specialty',data->>'specialty','bio',data->>'bio','image',data->>'image')) FROM public.gym_records WHERE gym_id=g AND kind='trainers'),'[]'::jsonb)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.client_gym_content(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.client_gym_content(uuid) TO authenticated;